local mini_game_base = newclass('MazeEscapeBase')

function mini_game_base:init(controller, game_data)
	-- 미니 게임의 컨트롤러
	self.controller = controller

	-- 미니 게임이 플레이 되고 있는지 확인하기 위한 플래그.
	self.is_game_playing = false

	-- 미니 게임의 이름
	self.game_name = game_data.game_name
end

function mini_game_base:game_start()
	CS.UnityEngine.Debug.Log("GameStart() from MazeEscapeBase Maze Escape")
end

function mini_game_base:on_event(e)
end

function mini_game_base:on_succeed()
end

function mini_game_base:on_failed()
end

function mini_game_base:reset()
end

function mini_game_base:dispose()
end

return {
	create = function()
		return mini_game_base
	end
}

